/// The chimes Belltide can play. Ids match the Android sound pool
/// (android/app/src/main/kotlin/.../service/ChimePlayer.kt) and the files
/// generated by tool/generate_chimes.py.
enum ChimeSound {
  bell('bell', 'Bell'),
  bowl('bowl', 'Singing bowl'),
  chime('chime', 'High chime'),
  doubleBell('double', 'Double bell'),
  wood('wood', 'Wood block'),
  gong('gong', 'Gong'),
  rise('rise', 'Rising bells'),
  beep('beep', 'Beep'),
  none('none', 'Silent');

  const ChimeSound(this.id, this.label);

  final String id;
  final String label;

  bool get isSilent => this == ChimeSound.none;

  /// Every sound that actually makes a noise.
  static List<ChimeSound> get audible =>
      values.where((s) => !s.isSilent).toList(growable: false);

  static ChimeSound fromId(Object? id, {ChimeSound fallback = ChimeSound.bell}) {
    for (final sound in values) {
      if (sound.id == id) return sound;
    }
    return fallback;
  }
}
